  LanguageConfig_BonusCardRateText_CN = {
    Text = "\"A semente mãe\" adquire bônus de grande desejo: <NetworkDelayGreen:{s1}>"
  },
  LanguageConfig_BonusCardTipsContent_CN = {
    Text = "1. O Guardião que possui um Corpo Desperto ou Roda do Destino específico (não é necessário estar em campo) pode fazer com que a recompensa da missão do nível \"Desejo Caótico\" contenha um aumento extra na queda do \"Núcleo de Fertilidade\" (incluindo reprodução), com os seguintes aumentos: \n· Corpo Desperto \"Thais\": Despertar Espiritual 0/1/2/3 e acima, aumento de 20%/30%/40%/50% \n· Roda do Destino SSR \"Nutrição Misericordiosa\": Posição sobreposta 0/1/2/3 e acima, aumento de 20%/30%/40%/50% \n· Roda do Destino SR \"Beijo Ardente de Despedida\": Posição sobreposta 0/1/2/3 e acima, aumento de 20%/30%/40%/50% \n2. Os \"Aumentos de Desejo\" de diferentes Corpos Despertos ou Rodas do Destino são calculados de forma acumulativa."
  },
  LanguageConfig_BonusCardTipsTitle_CN = {
    Text = "Descrição do bônus de ganância"
  },
  LanguageConfig_BonusRuleContent_A24Activity_CN = {
    Text = "1. O Guardião que possui um Corpo Desperto ou Roda do Destino específica (não é necessário estar em campo) pode fazer com que a recompensa da missão da fase \"Código de memória\" receba um bônus adicional de queda (incluindo reprodução), os bônus específicos são os seguintes: \n· Corpo Desperto \"24\": Despertar 0/1/2/3 ou mais, bônus de 20%/30%/40%/50% \n· Roda do Destino SSR \"Restituição do corpo deformado\": Posição sobreposta 0/1/2/3 ou mais, bônus de 20%/30%/40%/50% \n· Roda do Destino SR \"Determinação do Bacalhau Prateado\": Posição sobreposta 0/1/2/3 ou mais, bônus de 20%/30%/40%/50% \n2. Os \"bônus racionais\" de diferentes Corpos Despertos ou Rodas do Destino são calculados de forma acumulativa."
  },
  LanguageConfig_BonusRuleContent_ArachneActivity_CN = {
    Text = "1,O Guardião que possui um Corpo Desperto ou Roda do destino específico (não é necessário estar em campo) pode fazer com que o \"Palco da Marionete\" tenha um aumento nas recompensas da missão, com o \"Bilhete de assento em veludo\" recebendo um bônus de queda adicional, conforme detalhado a seguir: \n· Corpo Desperto \"Arachne\": Despertar Espiritual 0/1/2/3 e acima, bônus de 20%/30%/40%/50%. \n· Roda do destino SSR \"Rede da Tecelagem Eterna\": Posição sobreposta 0/1/2/3 e acima, bônus de 20%/30%/40%/50%. \n· Roda do destino SR \"Roda de fiar do destino\": Posição sobreposta 0/1/2/3 e acima, bônus de 20%/30%/40%/50%. \n2,Os \"bônus de atividade\" de diferentes Corpos Despertos ou Rodas do destino são calculados de forma acumulativa."
  },
  LanguageConfig_BonusRuleContent_CarabooActivity_CN = {
    Text = "1. Guardiões do segredo que possuem Corpos Despertos ou Rodas do destino específicos (não é necessário implantá-los) podem obter bônus de drop adicionais para \"Maçã Carmesim\", \"Maçã Dourada\" e \"Maçã Caramelada\" nas recompensas de missão da fase \"Tesouros de Umapati\". Os bônus específicos são os seguintes:\nCorpo Desperto \"Caraboo\": Despertar Espiritual 0/1/2/3 ou acima, bônus de 20%/30%/40%/50%.\nRoda do destino SSR \"Mentira da Fruta Doce\": Posição sobreposta 0/1/2/3 ou acima, bônus de 20%/30%/40%/50%.\nRoda do destino SR \"Verdade serena\": Posição sobreposta 0/1/2/3 ou acima, bônus de 20%/30%/40%/50%.\n2. Os \"Bônus de Evento\" de diferentes Corpos Despertos ou Rodas do destino são calculados de forma cumulativa."
  },
  LanguageConfig_BonusRuleContent_CastorActivity_CN = {
    Text = "1. O Guardião que possui um Corpo Desperto ou Roda do Destino específico (não é necessário estar em batalha) pode fazer com que as recompensas da missão do nível \"Salto para o Céu Azul\", como o \"Livro de senso comum\", \"Livro de Matemática\" e \"Livro de literatura\", recebam um bônus extra de queda, conforme detalhado abaixo: \n· Corpo Desperto \"Castor\": Despertar 0/1/2/3 ou mais, bônus de 20%/30%/40%/50%. \n· Roda do Destino SSR \"Liberdade Inquebrável\": Posição sobreposta 0/1/2/3 ou mais, bônus de 20%/30%/40%/50%. \n· Roda do Destino SR \"Pena Solitária\": Posição sobreposta 0/1/2/3 ou mais, bônus de 20%/30%/40%/50%. \n2. Os \"bônus de evento\" de diferentes Corpos Despertos ou Rodas do Destino são calculados de forma acumulativa."
  },
  LanguageConfig_BonusRuleContent_ClementineActivity_CN = {
    Text = "1. O Guardião que possui um Corpo Desperto ou Roda do Destino específica (não é necessário estar em campo) pode fazer com que o \"Relatório de diagnóstico\" na recompensa da missão da fase \"Cura do Medo\" receba um bônus de queda adicional (incluindo Reproduzir), com os seguintes bônus: \n· Corpo Desperto \"Clementine\": Despertar Espiritual 0/1/2/3 e acima, bônus de 20%/30%/40%/50% \n· Roda do Destino SSR \"Angústia Velada\": Posição sobreposta 0/1/2/3 e acima, bônus de 20%/30%/40%/50% \n· Roda do Destino SR \"Pêndulo Hipnótico\": Posição sobreposta 0/1/2/3 e acima, bônus de 20%/30%/40%/50% \n2. Os \"bônus de evento\" de diferentes Corpos Despertos ou Rodas do Destino são calculados de forma acumulativa."
  },
  LanguageConfig_BonusRuleContent_DaffodilActivity_CN = {
    Text = "1. O Guardião que possui um Corpo Desperto ou Roda do Destino específico (não é necessário estar em campo) pode fazer com que as recompensas da missão do nível \"Loja da Bruxa\" recebam um bônus adicional nas quedas de \"Crânio do Animal Pálido\", \"Crânio de Fera Sombria\" e \"Crânio do Animal Escarlate\" (incluindo reprodução), com os seguintes bônus: \n· Corpo Desperto \"Daffodil\": Despertar Espiritual 0/1/2/3 ou mais, bônus de 20%/30%/40%/50% \n· Roda do Destino SSR \"Raridade Preciosa\": Posição sobreposta 0/1/2/3 ou mais, bônus de 20%/30%/40%/50% \n· Roda do Destino SR \"Chapéu de Bruxa de Aba Larga\": Posição sobreposta 0/1/2/3 ou mais, bônus de 20%/30%/40%/50% \n2. O \"bônus de evento\" de diferentes Corpos Despertos ou Rodas do Destino será contabilizado de forma acumulativa."
  },
  LanguageConfig_BonusRuleContent_DoresainActivity_CN = {
    Text = "1. O Guardião que possui um Corpo Desperto ou Roda do destino específico (não é necessário estar em campo) pode fazer com que o \"Banquete de Devorar Almas\" receba um aumento adicional nas recompensas de \"Ossos Podres da Mão\", com os seguintes bônus: \n· Corpo Desperto \"Doresain\": Despertar Espiritual 0/1/2/3 e acima, bônus de 20%/30%/40%/50%.\n· Roda do destino SSR \"Beijo do Repouso\": Posição sobreposta 0/1/2/3 e acima, bônus de 20%/30%/40%/50%.\n· Roda do destino SR \"Iguaria Macabra\": Posição sobreposta 0/1/2/3 e acima, bônus de 20%/30%/40%/50%.\n2. Os \"bônus de evento\" de diferentes Corpos Despertos ou Rodas do destino são calculados de forma acumulativa."
  },
  LanguageConfig_BonusRuleContent_GenesisTinctActivity_CN = {
    Text = "1. Guardiões do segredo que possuem Corpos Despertos ou Rodas do destino específicos (implantação não necessária) obtêm bônus de drop adicionais para \"Suggested Translation\" nas recompensas de missão da fase \"Suggested Translation\" (incluindo Reproduzir). Os bônus específicos são os seguintes:\nCorpo Desperto \"Lotan: Cetarcon\": Despertar Espiritual 0/1/2/3 ou acima, bônus de 20%/30%/40%/50%.\nRoda do destino SSR \"Suggested Translation\": Posição sobreposta 0/1/2/3 ou acima, bônus de 20%/30%/40%/50%.\nRoda do destino SR \"Suggested Translation\": Posição sobreposta 0/1/2/3 ou acima, bônus de 20%/30%/40%/50%.\n2. Os \"Bônus de Evento\" de diferentes Corpos Despertos ou Rodas do destino são calculados de forma cumulativa."
  },
  LanguageConfig_BonusRuleContent_HamelnActivity_CN = {
    Text = "1. O Guardião que possui um Corpo Desperto ou Roda do Destino específica (não é necessário estar em campo) pode fazer com que a recompensa da missão do nível \"Som tonante\" tenha um bônus adicional na \"Canto heroico\" (incluindo Reproduzir), com os seguintes bônus: \n· Corpo Desperto \"Hameln\": Despertar 0/1/2/3 ou mais, bônus de 20%/30%/40%/50% \n· Roda do Destino SSR \"Réquiem Eterno\": Posição sobreposta 0/1/2/3 ou mais, bônus de 20%/30%/40%/50% \n· Roda do Destino SR \"Apresentação que Nunca Para\": Posição sobreposta 0/1/2/3 ou mais, bônus de 20%/30%/40%/50% \n2. Os \"bônus de Canto\" de diferentes Corpos Despertos ou Rodas do Destino são calculados de forma acumulativa."
