  LanguageConfig_DailyChallengeExpAttenuationRulesTipsTitle_CN = {Text = "Regras"},
  LanguageConfig_DailyChallengeExpAttenuationRulesTips_CN = {
    Text = "·Quando o \"Nível do Guardião\" ou o \"Nível médio da equipe\" for significativamente superior ao nível recomendado da fase de desafio, a experiência de Mergulho Profundo obtida será reduzida."
