  LanguageConfig_LotteryPhoneticDialogue10_CN = {
    Text = "Seja mais devoto, sacrifique mais... O reino de Deus observa sua oração, e um dia ele lhe responderá"
  },
  LanguageConfig_LotteryPhoneticDialogue11_CN = {
    Text = "Mesmo a pessoa mais comum pode ser tocada por esses versos... Esta flor desabrocha para você!"
  },
  LanguageConfig_LotteryPhoneticDialogue12_CN = {
    Text = "A poesia tem suas próprias emoções, assim como as flores têm suas linguagens. Isto é para você"
  },
  LanguageConfig_LotteryPhoneticDialogue13_CN = {
    Text = "Preste atenção, eu lutarei eternamente"
  },
  LanguageConfig_LotteryPhoneticDialogue14_CN = {
    Text = "Você veio testemunhar meu triunfo?"
  },
  LanguageConfig_LotteryPhoneticDialogue15_CN = {
    Text = "Esforce-se, lute, bom garoto, quer que o professor acaricie sua cabeça?"
  },
  LanguageConfig_LotteryPhoneticDialogue16_CN = {
    Text = "Com esses destroços, o que você pode salvar?"
  },
  LanguageConfig_LotteryPhoneticDialogue17_CN = {
    Text = "Oops, o convidado tem muita sorte! Quer tentar mais uma vez?"
  },
  LanguageConfig_LotteryPhoneticDialogue18_CN = {
    Text = "Quer dar uma olhada novamente? A loja ainda tem mercadorias mais valiosas."
  },
  LanguageConfig_LotteryPhoneticDialogue19_CN = {
    Text = "Este relatório é muito saboroso, obrigado pela hospitalidade."
  },
  LanguageConfig_LotteryPhoneticDialogue1_CN = {
    Text = "Obrigado pelo carinho, querido"
  },
  LanguageConfig_LotteryPhoneticDialogue20_CN = {
    Text = "Hmm, recebido. Algo mais?"
  },
  LanguageConfig_LotteryPhoneticDialogue21_CN = {
    Text = "Obrigado pelo seu presente, por favor aceite isto também."
  },
  LanguageConfig_LotteryPhoneticDialogue22_CN = {
    Text = "Encontrei alguns materiais valiosos, espero que possam te ajudar."
  },
  LanguageConfig_LotteryPhoneticDialogue23_CN = {
    Text = "Uma entrada simples, desejo-lhe uma boa refeição."
  },
  LanguageConfig_LotteryPhoneticDialogue24_CN = {
    Text = "O prato principal preparado pessoalmente pelo Santo Senhor está de seu agrado, convidado?"
  },
  LanguageConfig_LotteryPhoneticDialogue25_CN = {
    Text = "Não se preocupe demais com técnicas e regras."
  },
  LanguageConfig_LotteryPhoneticDialogue26_CN = {
    Text = "A razão só ensina a copiar, a loucura é que permite criar."
  },
  LanguageConfig_LotteryPhoneticDialogue27_CN = {
    Text = "As pessoas temem a loucura porque nunca viram a realidade."
  },
  LanguageConfig_LotteryPhoneticDialogue28_CN = {
    Text = "Você viu? O mundo real!"
  },
  LanguageConfig_LotteryPhoneticDialogue29_CN = {
    Text = "Eu vi as cores reais, que maravilha."
  },
  LanguageConfig_LotteryPhoneticDialogue2_CN = {
    Text = "Ah, que sorte! Pegue isso"
  },
  LanguageConfig_LotteryPhoneticDialogue30_CN = {
    Text = "A loucura e o absurdo são a verdadeira beleza da realidade, a beleza da arte!"
  },
  LanguageConfig_LotteryPhoneticDialogue31_CN = {
    Text = "Preto, o preto ainda está aqui, continue lavando seus pecados."
  },
  LanguageConfig_LotteryPhoneticDialogue32_CN = {
    Text = "Que beleza, eu vi a sua alma pura…"
  },
  LanguageConfig_LotteryPhoneticDialogue33_CN = {
    Text = "Ei, guardião! Mesmo que a situação acontecesse de novo, você me salvaria, certo?\n… Então eu poderia dormir tranquilo. Obri, ahem, quero dizer, obrigado."
  },
  LanguageConfig_LotteryPhoneticDialogue34_CN = {
    Text = "Recentemente tenho sonhado com coisas do passado, está me irritando, seria melhor se isso tivesse alguma utilidade."
  },
  LanguageConfig_LotteryPhoneticDialogue35_CN = {
    Text = "A Mãe Divina fez um sacrifício sublime pelo Reino Divino, estamos dispostos a trocar tudo pela sua paz."
  },
  LanguageConfig_LotteryPhoneticDialogue36_CN = {
    Text = "Muito obrigado pela oferenda à Mãe Divina, espero que isso lhe traga uma boa noite de sono."
  },
  LanguageConfig_LotteryPhoneticDialogue37_CN = {
    Text = "Este sonho vai continuar a se repetir eternamente, e você... \n Agradeça, eu vou permitir que você se junte a ele."
  },
  LanguageConfig_LotteryPhoneticDialogue38_CN = {
    Text = "Você já viu como é o meu sonho? Aquela cena não limpa e imunda até o extremo..."
