  LanguageConfig_LotteryPhoneticDialogue39_CN = {
    Text = "Possesões materiais são tão redundantes. Se você tiver algum desejo, sinta-se à vontade para falar diretamente comigo..."
  },
  LanguageConfig_LotteryPhoneticDialogue3_CN = {
    Text = "Você, jovem, encontrou um tesouro. Tudo na minha loja são relíquias antigas!"
