  LanguageConfig_RPGJJC_Desc_CN = {
    Text = "Você pode consumir \"Credencial de Treinamento\" para desafiar as equipes de defesa montadas por outros Guardiões. Se o desafio for bem-sucedido, sua classificação será elevada. Você também precisa montar cuidadosamente sua equipe de defesa, ou poderá ser desafiado com sucesso por outros Guardiões, resultando em uma queda na classificação. Quanto maior a classificação, mais \"Insígnias de Treinamento\" você receberá a cada hora. As \"Credenciais de Treinamento\" serão obtidas automaticamente ao longo do tempo. As \"Insígnias de Treinamento\" podem ser trocadas na loja de recompensas por Cupons de Ouro Rosa, Elixires de Gnosis e outros itens."
  },
