  LanguageConfig_RailWayStageCrazyMileExpGetDescV2_CN = {
    Text = "Um máximo de {s1} Pontos de Convidados VIP pode ser obtido nesta Operação de investigação.\n{s3} Corpos de Gnosis de Emergência foram usados; {s2} Pontos de Convidados VIP foram obtidos até agora.\n  ·Fase 1: Derrotar Elite/Chefe para obter Pontos de Convidados VIP ×25/75\n  ·Fase 2: Derrotar Elite/Chefe para obter Pontos de Convidados VIP ×50/150\n  ·Fase 3: Derrotar Elite/Chefe para obter Pontos de Convidados VIP ×75/225\n  ·Os Pontos de Convidados VIP obtidos na Dificuldade/Loucura são aumentados em 150%/400%.\n  ·Derrotar o Chefe da Fase 4 na Dificuldade de Loucura concede adicionalmente Pontos de Convidados VIP × 1500.\n  ·Cada Corpo de Gnosis de Emergência usado reduz os Pontos de Convidados VIP em 20%."
  },
  LanguageConfig_RailWayStageCrazyMileExpGetDesc_CN = {
    Text = "Máximo de Pontos de Convidados VIP disponíveis nesta investigação: {s1}. \nCorpo de Gnosis de Emergência utilizado: {s3}. Atualmente obtidos: {s2} Pontos de Convidados VIP.\nFase 1: Derrotar a elite/líder concede 25/75 Pontos de Convidados VIP.\nFase 2: Derrotar a elite/líder concede 50/150 Pontos de Convidados VIP.\nFase 3: Derrotar a elite/líder concede 75/225 Pontos de Convidados VIP.\nDificuldade Difícil/Loucura aumenta os Pontos de Convidados VIP obtidos em 150%/400%.\nCada uso do Corpo de Gnosis de Emergência reduz os Pontos de Convidados VIP em 20%."
  },
  LanguageConfig_RailWayStageCrazyNowDescV2_CN = {
    Text = "A dificuldade de loucura tem 4 fases. Cada uma das 3 primeiras fases contém 6 batalhas. A 4ª fase desafia diretamente o Líder final.\nAtualmente na Fase {s1} - Batalha {s2}."
  },
  LanguageConfig_RailWayStageCrazyNowDesc_CN = {
    Text = "A investigação atual terá 3 fases, com 6 batalhas em cada fase. \n Atualmente está na fase {s1} - batalha {s2}."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent1_CN = {
    Text = "<Title:Recompensas de Fase>\nPrimeira Fase: Derrotar a elite/Líder para ganhar \"Pontos de Convidados VIP\" ×25/75 \nSegunda Fase: Derrotar a elite/Líder para ganhar \"Pontos de Convidados VIP\" ×50/150 \nTerceira Fase: Derrotar a elite/Líder para ganhar \"Pontos de Convidados VIP\" ×75/225\n<Title:Criação Inicial>\nNo início da investigação, ganhe a criação \"Câmera Impecável da Pequena N\".\n<OrangeQuality:Harmonia Dourada>: \"Ajuste de potência de cálculo\" agora só aumenta o Consumo de potência de cálculo em 1. Cada 1% de Dano potencializado aumenta a Profundidade da Pesquisa da Consciência em 1%.\n<RedQuality:Cansaço de longa distância>: Efeitos de recuperação de vida em batalha são reduzidos em 50%."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent2_CN = {
    Text = "<Title:Regras Especiais>\nQuanto maior a dificuldade, mais Pontos de Convidados VIP você ganhará. Se completar todas as três Fases, os Pontos de Convidados VIP aumentam em 150%.\n<Title:Criação Inicial>\nNo início da investigação, ganhe a criação \"Câmera Desgastada da Pequena N\".\n<OrangeQuality:Harmonia Dourada>: \"Ajuste de potência de cálculo\" agora só aumenta o Consumo de potência de cálculo em 1. Cada 1% de Dano potencializado aumenta a Profundidade da Pesquisa da Consciência em 1%.\n<OrangeQuality:Presente Dimensional>: No início da exploração, ganhe aleatoriamente 1 criação de Dimensão. Limite de Mão +1.\n<RedQuality:Cansaço de longa distância>: Os efeitos de recuperação de vida em batalha são reduzidos em 50%.\n<RedQuality:Sinais de tontura>: No início da batalha, a Fúria/Energia de chave atual de todos os Corpos Despertos é reduzida em 50%."
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3V2_CN = {
    Text = "<Title:Desafio Especial>\nNa dificuldade de loucura, após completar a terceira fase, haverá um desafio adicional com o Líder final da quarta fase \"Tawil\".\n<Title:Recompensas de Fase>\nQuanto maior a dificuldade do desafio, mais \"Pontos de Convidados VIP\" você obterá. Os \"Pontos de Convidados VIP\" obtidos ao completar as três fases aumentam em 400%\nApós derrotar o Líder final \"Tawil\", você pode obter adicionalmente \"Pontos de Convidados VIP\" × 1500.\n<Title:Criações Iniciais>\nAo iniciar a investigação, você obtém a Criação \"Câmera Caótica da Pequena N\"\n·<OrangeQuality:Harmonia Dourada>: O efeito máximo de aumento de Poder de cálculo trazido pelo \"Ajuste de potência de cálculo\" é de 1 ponto. Para cada 1% de Dano potencializado que você possuir, o efeito de Profundidade da Pesquisa da Consciência aumenta em 1%.\n·<OrangeQuality:Presente Dimensional>: Ao iniciar a exploração, você obtém aleatoriamente 1 Criação de Imagem Dimensional e o Limite de cartas na mão aumenta em 2.\n·<OrangeQuality:Ritual Bendito>: As recompensas por derrotar os Líderes da primeira e segunda fase são alteradas para 1 Criação Bendita aleatória entre 3 opções.\n·<RedQuality:Cansaço de longa distância>: Durante o combate, todos os efeitos de recuperação de Vida são reduzidos em 50%.\n·<RedQuality:Sinais de tontura>: Ao iniciar o combate, a Fúria atual e a Energia da Chave de Prata de todos os Corpos Despertos são reduzidas em 50%.\n·<RedQuality:Corredor da Noite Eterna>: Ao iniciar a exploração, o limite máximo de Aliemus Base e Energia da Chave de Prata de todos os Corpos Despertos aumenta em 50%"
  },
  LanguageConfig_RailWayStageDifficultyBuffContent3_CN = {
    Text = "<Title:Regras Especiais>\nQuanto maior a dificuldade, mais Pontos de Convidados VIP você ganhará. Se completar todas as três Fases, os Pontos de Convidados VIP aumentam em 400%.\n<Title:Criação Inicial>\nNo início da investigação, ganhe a criação \"Câmera Caótica da Pequena N\".\n<OrangeQuality:Harmonia Dourada>: \"Ajuste de potência de cálculo\" agora só aumenta o Consumo de potência de cálculo em 1. Cada 1% de Dano potencializado aumenta a Profundidade da Pesquisa da Consciência em 1%.\n<OrangeQuality:Presente Dimensional>: No início da exploração, ganhe aleatoriamente 1 criação de Dimensão. Limite de Mão +2.\n<OrangeQuality:Ritual Bendito>: As recompensas do Líder da Fase 1 e Fase 2 mudam para 3 opções de Criações Benditas.\n<RedQuality:Cansaço de longa distância>: Os efeitos de recuperação de vida são reduzidos em 50%.\n<RedQuality:Sinais de tontura>: No início da batalha, a Fúria atual e a Energia de chave de todos os Corpos Despertos são reduzidas em 50%.\n<RedQuality:Corredor da Noite Eterna>: O limite de Fúria Básica e de Energia de chave de todos os Corpos Despertos aumenta em 50%."
  },
