  LanguageConfig_ReplayTabRule_CN = {
    Text = "<Title:[Modo de Investigação]>\n·Após concluir investigações em operações, Reino sem luz e eventos de jogabilidade temporária, você pode visualizar os registros correspondentes aqui.\n·Os desafios falhos no modo de investigação não serão registrados.\n·Atualmente, apenas a reprodução da última batalha na fase é suportada.\n\n<Title:[Reprodução]>\n·Você pode inserir o registro da batalha no campo abaixo para assistir à reprodução correspondente.\n·Os registros de batalha podem ser copiados e compartilhados a partir das interfaces \"Dados de Investigação\" no modo de investigação e \"Liquidação de Batalha\" na fase de duelo.\n·\"Operação de investigação\" e \"Fase de Duelo\" podem salvar no máximo 100 registros cada, e os registros são mantidos por até 30 dias."
