  LanguageConfig_ResonanceUnlock_And_CN = {Text = "E"},
  LanguageConfig_ResonanceUnlock_Or_CN = {Text = "Ou"},
  LanguageConfig_ResonanceUpgradeText_CN = {Text = "Melhoria"},
  LanguageConfig_Resonance_Group_Desc_1_CN = {
    Text = "No ponto [presente gentil], você pode adicionar 1 [retribuição inocente] ao seu baralho—custo de aritmética 1, concedendo a um despertador com o menor nível de exaltar 30 exaltações, consumindo"
  },
  LanguageConfig_Resonance_Group_Desc_24_CN = {
    Text = "No evento \"Caminho da Loucura\", designa um Corpo Desperto, causando a divisão de espírito, perdendo as quatro cartas de comando iniciais. Somente então o caminho avançado aparecerá, permitindo que você ganhe uma Criação de Ouro entre 3 opções. \n Você pode recuperar as cartas de comando perdidas uma a uma nos quatro eventos de \"Fragmento de Espírito\" subsequentes, e as cartas de comando recuperadas terão diretamente a gravura única <EnsembleKeywords:\"ensemble\">."
  },
  LanguageConfig_Resonance_Group_Desc_2_CN = {
    Text = "No nó [Estátua de Cera Inacabada], escolha 1 carta e reduza seu custo de Aritmética em 1."
  },
  LanguageConfig_Resonance_Group_Desc_3_CN = {
    Text = "No ponto [pústula estranha], você pode adicionar uma carta [Coração de Deformidade] ao seu baralho, com custo de 0, ao jogá-la descarte todas as cartas da mão e compre cartas igual ao número de descartes + 1, consumindo"
  },
  LanguageConfig_Resonance_Group_Desc_4_CN = {
    Text = "No ponto [mel doce], você pode adicionar uma carta [mel doce] ao seu baralho—custo de aritmética 1, ganhando 1 camada de barreira temporária, consumindo"
  },
  LanguageConfig_Resonance_Group_Desc_5_CN = {
    Text = "Nos nós da fase \"Délirante dos abismos\" e nas fases seguintes, você pode obter o efeito \"Membro de Poço Divino\" — causa dano equivalente a 10% da vida máxima da sua equipe aos inimigos na linha da frente ao final do turno. \n Você pode adicionar uma carta \"O Julgamento do Intermediário\" ao seu baralho — Consumo de 0 de poder de cálculo, ao dispará-la, perde 10% da vida atual, fazendo com que \"Membro de Poço Divino\" cause 3 vezes mais dano aos inimigos na linha de trás, e se for em uma batalha contra um chefe, causa 10 vezes mais dano. Consumo."
  },
  LanguageConfig_Resonance_Group_Desc_6_CN = {
    Text = "No \"mastro branco puro\", adicione um \"véu utópico\" ao baralho. Custo de 1 de aritmética, veja 3 chaves diferentes das que você possui e escolha 1 para liberar imediatamente, sem ativar os cooldowns de chaves. Na batalha contra chefes, pode ser usado 1 vez a mais. Custo"
  },
  LanguageConfig_Resonance_Group_Desc_7_CN = {
    Text = "Perto do início da exploração, encontre um evento especial de Ressonância—[Mãe Nutriente]. Escolha um Cartão de Comando para receber a especial Oração [Nutriente], mas também ganhe 3 Cartões de Sintoma aleatórios.\nOração [Nutriente]: O Cartão ganha Retenção. Se estiver na mão no final do turno, ganhe uma cópia original que também tenha Retenção e Exausto."
  },
  LanguageConfig_Resonance_Group_Desc_8_CN = {
    Text = "Próximo ao ponto de partida da exploração, você encontrará um evento de ressonância especial ——[Cerimônia de Admissão], adicione[Luz tênue da noite polar] à pilha de cartas.\n[Luz tênue da noite polar] : Escolha 1 carta de comando do Mazo de robo ou do Monte de descarte para colocar na mão, tornando seu Consumo de potência de cálculo 0. Consome após 1 uso."
  },
  LanguageConfig_Resonance_Group_Desc_9_CN = {
    Text = "Próximo ao ponto de partida da exploração, você encontrará um evento de Ressonância especial [Cerimônia de entrada]. Adicione [Luz tênue da noite polar] à pilha de cartas e herde todos os bônus do capítulo 8."
  },
  LanguageConfig_Resonance_Group_Desc_D05EX_CN = {
    Text = "Obtenha a Criação inicial \"Equipe de Pesquisa\": Inicialmente possui 30 membros da expedição. No início da batalha, coloque 5 cartas de \"Suspeita\" no baralho. \"Suspeita\": ao disparar, escolherá consumir diferentes números de membros da expedição, obtendo diferentes efeitos. \n Durante o processo de exploração, você enfrentará constantemente a decisão de \"Suspeita\", perdas de membros da expedição e, ao acionar o Ponto de contato, ainda terá a oportunidade de obter resgate. Por fim, ao evacuar com segurança, receberá a \"Medalha de Resgate\" com base no número restante de membros da expedição; quanto mais membros evacuados, mais poderosa será a \"Medalha de Resgate\"."
  },
  LanguageConfig_Resonance_Group_Desc_Horla_CN = {
    Text = "Ao começar a exploração, ganhe a criação inicial \"A caneta e a tinta de Aurora\": Após a batalha, ganhe 1 camada de \"Tinta\", ao atingir 2 camadas, consuma e coloque aleatoriamente 1 carta \"Imagem\" no baralho.\nPode escolher \"Compor Oferta\" em um evento especial de ressonância [Presente da Primavera]: escolha 3 cartas de \"Imagem\" e faça com que Horla crie um \"Poema de ofrenda\" para você."
  },
  LanguageConfig_Resonance_Group_Desc_Lily_CN = {
    Text = "No evento de ressonância \"O Dilema do Produtor\", a opção \"Pedindo Ajuda a um Parceiro\" pode proporcionar uma oração avançada 3 de 1"
  },
  LanguageConfig_Resonance_Group_Desc_MLYM_CN = {
    Text = "No início da exploração, adicione 3 cartas de benefício ao deck: <DerivativeCardKeywords_57:\"Lar Aconchegante\">, <DerivativeCardKeywords_58:\"Amigo sincero\">, <DerivativeCardKeywords_59:\"Vida estável\">. \n \"Lar Aconchegante\": obtenha 2 pontos de poder de cálculo. \n \"Amigo sincero\": aplique 1 camada de fraqueza e vulnerável a todos os inimigos. \n \"Vida estável\": compre 2 cartas."
  },
  LanguageConfig_Resonance_Group_Desc_Railway_CN = {
    Text = "A preencher."
  },
  LanguageConfig_Resonance_Group_Desc_SEWD_CN = {
    Text = "O evento \"Desejo\" concede uma Relíquia do Pecado aleatória ou Relíquia de Ouro; o evento \"Arrependimento\" purifica uma Relíquia do Pecado em uma Relíquia Abençoada; o evento \"Redenção\" permite que você exclua uma carta de sintoma para uma recompensa."
  },
  LanguageConfig_Resonance_Group_Desc_Wangda_CN = {
    Text = "No evento de ressonância \"Designe a Ordem Oculta\", a opção \"Obter Financiamento\" pode proporcionar 25 selos negros e uma relíquia de prata aleatória"
  },
  LanguageConfig_Resonance_Group_Desc_x1_CN = {
    Text = "Durante o evento de ressonância \"Consciência Ainda Não Perdida\", embaralhe uma carta \"Cérebro de Reserva\" no baralho. O \"Cérebro de Reserva\" pode armazenar temporariamente cartas que já foram usadas, decidindo em diferentes situações se devem ser retiradas e colocadas na mão."
  },
  LanguageConfig_Resonance_Group_Desc_x2_CN = {
    Text = "Na seção do evento \"Transformação da Vida\", escolha um despertado para transformá-lo em \"Inseto\".\nA recarga de loucura e a recarga de chave de prata dos \"Insetos\" aumentam em 50%, o custo de aritmética de todas as cartas de comando diminui em 1, mas elas serão consumidas após serem jogadas."
  },
  LanguageConfig_Resonance_Group_Desc_x3_CN = {
    Text = "No evento \"Cerimônia Pré-Lanche\", coloque 1 \"Especial da Noite dos Espíritos\" no baralho.\n\"Especial da Noite dos Espíritos\": custo de Aritmética 1, aumenta temporariamente a taxa crítica e o dano crítico de todos os Despertadores em 10%. Após jogar \"Especial da Noite dos Espíritos\", coloque 1 tipo de material nele, permitindo que ganhe um efeito específico permanentemente nesta batalha!"
  },
  LanguageConfig_Resonance_Group_Desc_x4_CN = {
    Text = "No evento \"Ilusão do Murphy\", coloque 3 \"Reflexões do Ciclo\" no baralho.\nAo jogar \"Reflexões do Ciclo\", descubra um \"Efeito de Lembrança\" para desencadeá-lo, consome. Depois do impacto: Todos os despertadores ganham 5 pontos de aliemus."
  },
