  LanguageConfig_StorylineGuide_0_CN = {
    Text = "Viver frente à morte."
  },
  LanguageConfig_StorylineGuide_10_CN = {
    Text = "Claro, o caos é o fim de tudo. Mas sempre há quem não queira desistir de lutar, não é?"
  },
  LanguageConfig_StorylineGuide_11_CN = {
    Text = "Não olhar diretamente para o universo acima da cabeça. Não olhar diretamente para o abismo interior."
  },
  LanguageConfig_StorylineGuide_12_CN = {
    Text = "Comer é a única virtude deste mundo."
  },
  LanguageConfig_StorylineGuide_13_CN = {
    Text = "Nenhum sonho sem limites tem resposta. Este sonho, é hora de acordar."
  },
  LanguageConfig_StorylineGuide_14_CN = {
    Text = "No palco do destino, os papéis que iremos desempenhar nunca foram uma escolha."
  },
  LanguageConfig_StorylineGuide_15_CN = {
    Text = "Ó Viajantes, caminhai suavemente por essa noite nevada. No cume das vontades vazias, que possais testemunhar o fim de um grande sonho."
  },
  LanguageConfig_StorylineGuide_16_CN = {
    Text = "Texto temporário"
  },
  LanguageConfig_StorylineGuide_17_CN = {
    Text = "Texto temporário"
  },
  LanguageConfig_StorylineGuide_18_CN = {
    Text = "Texto temporário"
  },
  LanguageConfig_StorylineGuide_19_CN = {
    Text = "Texto temporário"
  },
  LanguageConfig_StorylineGuide_1_CN = {
    Text = "Entre na perigosa névoa noturna de Londinium, Guardião. O seu caminho começa aqui."
  },
  LanguageConfig_StorylineGuide_20_CN = {
    Text = "Texto temporário"
  },
  LanguageConfig_StorylineGuide_2_CN = {
    Text = "Artista, louco, asceta, tolo... Esta cidade é sua galeria, as figuras de cera estão no início da história, ansiosas pela sua chegada."
  },
  LanguageConfig_StorylineGuide_3_CN = {
    Text = "O vento e a neve de Rai desprezam o massacre, ela espera por você, apenas para uma negociação. Ela trará a você o segredo que você tanto deseja. Seu preço é sempre cruel, sempre justo."
  },
  LanguageConfig_StorylineGuide_4_CN = {
    Text = "Lembre-se, lute por lembranças, morra por lembranças. Lembranças são nosso evangelho, nossa epígrafe. Além das lembranças, não temos nada."
  },
  LanguageConfig_StorylineGuide_5_CN = {
    Text = "Antes da queda das estrelas, oramos para o oceano: que o suave som das ondas nos proteja ao sonhar, que possamos retornar ao abraço da nossa terra natal, em um longo sonho sem despertar."
  },
  LanguageConfig_StorylineGuide_6_CN = {
    Text = "Cante — o antigo rei já viu novamente seu trono. O oráculo divino trará o reino de Deus para cada fiel devoto."
  },
  LanguageConfig_StorylineGuide_7_CN = {
    Text = "Ouça, reze, chame, reproduza, obedeça aos ideais mais nobres e aos desejos mais humildes. Em nome da mãe, Ele pode existir no Caos e no medo."
  },
  LanguageConfig_StorylineGuide_8_CN = {
    Text = "A luz eterna já acendeu, e essa luz sombria iluminará o caminho que leva ao seu destino final."
  },
  LanguageConfig_StorylineGuide_9_CN = {
    Text = "Diga a Ele, sua resposta."
  },
  LanguageConfig_StrongerTitle_CN = {
    Text = "Recolha materiais através do \"Interlúdio de Exercício\" e aumente o seu Despertado!"
  },
  LanguageConfig_StrongerWayTitle_CN = {
    Text = "Como ficar mais forte"
  },
  LanguageConfig_StrongerWay_CN = {
    Text = "· Desbloquear \"Operação de Investigação\" 1-2: Normal para acessar \"Ruínas da Dissolução\", que concede uma grande quantidade de materiais de desenvolvimento do Despertador. \n · Desbloquear \"Operação de Investigação\" 3-10: Normal para acessar \"Existência Transcendente\", que fornece uma quantidade substancial de materiais para atualização de habilidades do Despertador. \n · Desbloquear \"Nível de Investigação\" 15 para acessar \"Segundo Ciclo de Vida\", permitindo a equipagem de um segundo Ciclo para aumentar o poder de combate. \n · Desbloquear \"Nível de Investigação\" 25 para acessar \"Pacto Proibido\", que fornece um grande número de Pactos para aprimorar as habilidades do Despertador."
