  LanguageConfig_TrinketAutoRefine_CN = {
    Text = "<Title:Transcrição Automática>\nA Transcrição Automática pode realizar transcrições de forma rápida e em massa.\nDurante a Transcrição Automática, se um resultado de transcrição contiver 1 atributo desbloqueado com intensidade 8, a Transcrição Automática será interrompida.\nA Transcrição Automática pode ser realizada até 100 vezes.\nQuando os materiais forem insuficientes, a transcrição será interrompida automaticamente.\n<Title:Pular>\nDurante a Transcrição Automática, cada resultado de transcrição será exibido, e você pode optar por pular o processo de transcrição. Após pular, o resultado final da Transcrição Automática será exibido diretamente."
  },
