  LanguageConfig_TrinketBindNoneSelectedTips_CN = {
    Text = "Nenhum Mystik disponível para Vincular. Por favor, selecione pelo menos um."
  },
  LanguageConfig_TrinketBindRuleDesc_CN = {
    Text = "<Title:Imobilização de Mystik>\nOs Guardiões do segredo agora podem vincular Mystiks a Corpos Despertos.\nCada Corpo Desperto possui 6 slots de vinculação (um Mystik por slot).\nUma vez vinculado, o atributo primário do Mystik é aumentado em 50%.\nMystiks vinculados não aparecerão no seu Inventário nem no sistema de Alquimia.\nSe um Corpo Desperto não tiver nenhum Mystik equipado em uma formação ou slot de Suporte, o Mystik vinculado será equipado automaticamente.\nAtualizar um Mystik vinculado não o desvinculará; seus atributos aprimorados serão atualizados automaticamente.\n\n<Title:Desvincular Mystik>\nPara alterar ou remover uma vinculação, use a opção de desvincular na tela de Imobilização de Mystik.\nDesvincular um único slot custa 10 Mystiks do mesmo tipo (qualquer posição de slot pode ser usada como custo)."
  },
